SELECT dept_name, CASE WHEN budget >= 3163000 THEN 'high' WHEN budget >= 1879000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN location = 'Bangkok' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_bangkok, MIN(budget) AS min_budget FROM departments WHERE dept_name NOT IN ('Legal', 'Sales') AND dept_name IN ('Marketing', 'Engineering') GROUP BY dept_name, budget_bucket HAVING pct_bangkok < 61 ORDER BY dept_name DESC, pct_bangkok DESC
